r=load('reglementation')
edit(r,1,"Au jour du contrôle, quatre berlines diesel non hybrides, non classées en collection, remplissent les autres caractéristiques VTC. Laquelle respecte encore la limite d'ancienneté ?",["La voiture mise en circulation il y a six ans et neuf mois","La voiture mise en circulation il y a sept ans et un mois","La voiture mise en circulation il y a huit ans et deux mois","La voiture mise en circulation il y a neuf ans et six mois"],"Une voiture thermique non hybride et non de collection doit avoir moins de sept ans. Seule la première fiche retenue reste sous cette limite ; les autres conditions sont données conformes.")
edit(r,2,"Quatre voitures de cinq places, conformes sur les autres points, mesurent chacune 4,30 m. Laquelle bénéficie de l'exception aux dimensions minimales prévue pour les VTC ?",["La voiture entièrement électrique","La voiture diesel non hybride","La voiture essence non hybride","La voiture GPL non hybride"],"Les véhicules électriques et hybrides bénéficient de l'exception aux caractéristiques visées par l'arrêté, dont les dimensions. Les motorisations thermiques non hybrides proposées n'en bénéficient pas.")
edit(r,4,"Un exploitant compare quatre berlines thermiques non hybrides, conformes par ailleurs. Quelle fiche atteint le minimum de puissance nette VTC ?",["85 kW pour une puissance fiscale de 6 CV","82 kW pour une puissance fiscale de 7 CV","80 kW pour une puissance fiscale de 8 CV","83 kW pour une puissance fiscale de 9 CV"],"Le minimum est de 84 kW de puissance nette. Les CV fiscaux ne remplacent pas cette mesure : la fiche à 85 kW convient, même avec une puissance fiscale inférieure aux autres.")
edit(r,5,"Quatre berlines thermiques non hybrides ont quatre portes, cinq places, 90 kW et trois ans. Quelle fiche respecte aussi les dimensions minimales VTC, mesurées hors tout ?",["Longueur 4,62 m ; largeur 1,72 m","Longueur 4,48 m ; largeur 1,78 m","Longueur 4,70 m ; largeur 1,68 m","Longueur 4,49 m ; largeur 1,69 m"],"Il faut au moins 4,50 m de longueur et 1,70 m de largeur. La fiche 4,62 × 1,72 m respecte les deux seuils ; les autres échouent sur un ou deux, malgré leurs autres caractéristiques conformes.")
edit(r,6,"Un garage propose quatre véhicules thermiques non hybrides, tous conformes en dimensions, puissance, places et âge. Quel véhicule respecte également le minimum de portes pour le VTC ?",["Une berline à quatre portes","Un coupé à deux portes","Une citadine à trois portes","Un cabriolet à deux portes"],"Le véhicule doit avoir au moins quatre portes. La berline satisfait ce critère ; les autres caractéristiques sont indiquées conformes pour isoler cette comparaison.")
edit(r,7,"Un exploitant prépare quatre aménagements pour sa voiture VTC. Lequel présente un risque de confusion avec un équipement propre au taxi et doit être écarté ?",["Un dispositif lumineux de toit semblable au taxi","Un support intérieur pour le guidage du chauffeur","Un panneau amovible au nom du client à l'accueil","Un rangement intérieur pour les justificatifs"],"Un VTC ne doit pas être équipé d'un dispositif extérieur lumineux pouvant créer une confusion avec un taxi. Les autres aménagements décrits ne sont pas de tels dispositifs.")
edit(r,8,"Un professionnel compare des modes de pose pour ses vignettes VTC définitives. Quel montage répond à la fixation réglementaire ?",["Une pose collée dont le retrait détruit la vignette","Une pochette fixée par deux ventouses au vitrage","Un porte-document détachable sur la plage arrière","Une fixation magnétique retirée après le service"],"Les vignettes doivent être fixées de sorte qu'elles ne puissent pas être retirées sans être détruites. Une pose dans un support récupérable ne satisfait pas cette exigence.")
edit(r,11,r[10][0].replace("Quelle date borne ici l'usage de la vignette ?","Jusqu'à quelle date cette vignette peut-elle être utilisée ?"),["Le 12 juin","Le 2 juillet","Le 30 juin","Le 12 juillet"])
edit(r,12,"Une conductrice crée son activité indépendante. Sa carte professionnelle et sa déclaration d'entreprise sont obtenues ; son véhicule et ses garanties sont prêts. Quelle démarche distincte doit compléter le dossier d'exploitation ?",["L'inscription de l'exploitant au registre VTC","Le renouvellement du permis de conduire","La déclaration périodique des recettes à l'Urssaf","La demande de carte professionnelle personnelle"],"L'inscription sectorielle au registre VTC reste nécessaire. La création d'entreprise et la carte du conducteur ne se substituent pas à cette inscription de l'exploitant.")
edit(r,13,"Un exploitant a remplacé définitivement une voiture inscrite. Il classe cette formalité parmi quatre échéances de son agenda. Laquelle correspond à la transmission électronique du changement au gestionnaire du REVTC ?",["Dans les quinze jours francs du changement","Au moins trois mois avant l'échéance d'inscription","À la prochaine échéance quinquennale du registre","Au terme du mois de remplacement exceptionnel"],"Le changement des informations du dossier doit être signalé dans les quinze jours francs. Les autres délais proposés concernent le renouvellement ou le recours exceptionnel à un véhicule.")
edit(r,14,"Une inscription REVTC expire le 30 novembre. Quelle date de dépôt respecte le délai minimal pour demander son renouvellement avant cette échéance ?",["Le 30 août","Le 30 septembre","Le 30 octobre","Le 30 novembre"],"La demande doit précéder l'échéance d'au moins trois mois. Le 30 août respecte ce délai pour une échéance au 30 novembre ; les autres dates sont trop tardives.")
edit(r,15,"Une entreprise est inscrite au REVTC le 15 mars 2026. Sans modification de la durée normale de l'inscription, quelle année correspond à son échéance quinquennale ?",["2031","2027","2029","2033"],"L'inscription a une durée de cinq ans : mars 2026 conduit à mars 2031. L'âge du véhicule ou la date de la carte du chauffeur ne modifient pas cette durée.")
edit(r,17,"Pour quatre jours de festival, une entreprise déjà inscrite ajoute deux voitures et deux chauffeurs qui ne figurent pas dans son dossier. Quel ensemble de copies doit accompagner les dates de début et de fin du renfort déclaré ?",["Cartes grises des voitures et cartes professionnelles des chauffeurs","Permis des chauffeurs et devis acceptés des clients","Contrats de réservation et factures de location des voitures","Attestations de stage et relevés de chiffre d'affaires"],"La déclaration préalable du recours exceptionnel comporte les cartes grises, les cartes professionnelles et les dates prévues. Les documents commerciaux ou de formation ne remplacent pas ces pièces d'identification.")
edit(r,18,"Deux entreprises préparent une coopération. Chacune garde ses chauffeurs et sa comptabilité. Quelle proposition constitue précisément le prêt de numéro REVTC interdit, même sans paiement ?",["La seconde exploite sous l'inscription de la première","La seconde adresse un client à la première","La première demande un devis à la seconde","Les deux entreprises comparent leurs disponibilités"],"Le numéro d'inscription ne peut être prêté, même gratuitement. Une mise en relation ou un échange commercial entre entreprises ne se confond pas avec l'utilisation du numéro de l'autre pour exploiter.")
edit(r,20,"La SAS Horizon prépare son inscription au registre VTC. Son président est Éric, sa principale actionnaire sans mandat est Salomé, son conducteur référent est Karim et son comptable est Luc. Qui présente la demande en qualité de représentant légal décrite ici ?",["Éric, le président de la SAS","Salomé, l'actionnaire principale","Karim, le conducteur référent","Luc, le comptable de la société"],"La demande d'une personne morale est présentée par son représentant légal. Dans le dossier décrit, cette qualité appartient à Éric, président de la SAS.")
edit(r,21,"Le gestionnaire constate que le dossier d'inscription ne justifie pas une obligation requise. L'exploitant reçoit une invitation formelle à transmettre la pièce. À quelle étape de traitement cette invitation correspond-elle ?",["La régularisation du dossier avant un éventuel refus","La notification du renouvellement quinquennal","La radiation après cessation définitive d'activité","La validation d'une déclaration de renfort temporaire"],"Avant de refuser pour défaut de justification, le gestionnaire invite l'exploitant à fournir les pièces manquantes. Il ne s'agit ni d'une inscription déjà acquise ni d'une cessation d'activité.")
edit(r,22,"Une société cesse définitivement le VTC mais continue une autre activité. Quelle opération sur son dossier sectoriel correspond à cette situation ?",["La radiation de son inscription VTC","La mise à jour d'une voiture remplacée","Le renouvellement de l'inscription existante","La déclaration d'un renfort exceptionnel"],"La cessation définitive du VTC entraîne la radiation du registre sectoriel. La conservation de la société pour une autre activité ne justifie pas le maintien de cette inscription.")
edit(r,24,"Une assistante réserve une course au nom de son entreprise pour un visiteur. Lors du contrôle, les coordonnées requises du client réservataire manquent au justificatif. Quelle possibilité doit être offerte sans délai à l'agent dans le cadre de l'exception prévue par l'arrêté de 2025 ?",["Joindre directement le client réservataire","Joindre le seul visiteur transporté","Joindre l'assureur professionnel du chauffeur","Joindre le gestionnaire du registre VTC"],"L'exception impose de donner à l'agent les moyens de contacter directement le client sans délai. Le client qui réserve n'est pas nécessairement le passager : joindre seulement le visiteur ne suffit pas à établir cette possibilité.")
edit(r,25,"Lors d'un contrôle, un chauffeur présente sur son téléphone un justificatif numérique complet et consultable de la réservation. Quel document remplit ici la fonction de preuve de commande préalable ?",["Le justificatif affiché avec les mentions requises","La carte professionnelle conservée dans le véhicule","L'attestation d'inscription de l'exploitant","La vignette définitive portée par la voiture"],"La preuve de réservation peut être numérique. Ce justificatif concerne la course ; les documents de conducteur, d'exploitant ou de signalétique ne prouvent pas à eux seuls une commande préalable.")
edit(r,27,"Après la validation du véhicule, l'Imprimerie nationale envoie une signalétique temporaire avant les vignettes définitives. Quel fichier l'exploitant doit-il imprimer pour cet usage ?",["L'exemplaire de signalétique temporaire reçu","L'attestation d'inscription au registre national","La copie numérique de la carte du chauffeur","L'accusé de déclaration du véhicule au registre"],"La signalétique temporaire est le document transmis à cet effet par l'Imprimerie nationale. Les attestations du registre et la carte professionnelle remplissent d'autres fonctions.")
edit(r,29,"Après une dépose, un chauffeur n'a ni nouvelle réservation ni contrat avec le client final. Son établissement est éloigné. Quelle destination satisfait à la solution de stationnement permise par l'obligation nationale de retrait ?",["Le parking autorisé hors chaussée d'un partenaire","La station de taxis située devant la gare","La chaussée devant l'hôtel du dernier client","Le boulevard parcouru dans l'attente d'une demande"],"Sans réservation ni contrat avec le client final, le chauffeur doit rejoindre son établissement ou un lieu autorisé hors de la chaussée. Le parking proposé remplit cette seconde possibilité.")
edit(r,30,"Quatre chauffeurs viennent de déposer leur client. Lequel bénéficie de l'exception permettant de rejoindre directement une prochaine prise en charge, sans retour préalable à l'établissement ou stationnement hors chaussée ?",["Celui qui détient une nouvelle réservation confirmée","Celui qui espère une demande via son application","Celui qui voit des clients attendre devant un hôtel","Celui qui prévoit de se rapprocher d'une gare"],"Une réservation préalable pour une autre course permet de rejoindre la prise en charge suivante. Une simple possibilité de trouver un client n'est pas cette réservation.")
edit(r,31,"Un client accepte une course dont le prix sera calculé à la fin selon le temps et la distance. Quelle autre méthode un VTC peut-il également proposer pour une autre commande ?",["Un forfait déterminé dès la réservation","Un prix communal fixé par l'autorité de stationnement","Un tarif obligatoire lié au seul lumineux de toit","Un barème départemental imposé à tous les VTC"],"Le prix VTC est librement fixé : un forfait annoncé à la commande est possible, comme le calcul d'après le temps et la distance. Les autres propositions décrivent un encadrement qui n'est pas celui du prix VTC.")
edit(r,32,"Quatre voitures portent des vignettes définitives intactes. Dans quel dossier leur validité cesse-t-elle en raison de l'inscription de l'exploitant ?",["Inscription arrivée à échéance sans renouvellement","Carte du chauffeur renouvelée la semaine précédente","Facture de location réglée avec quelques jours de retard","Nouveau téléphone déclaré pour joindre l'entreprise"],"La validité des vignettes est liée à l'inscription de l'exploitant. Une inscription expirée sans renouvellement met fin à leur validité, même si les vignettes sont intactes.")
save('reglementation',r)
